const G=LIST.map(([i,n,c,o])=>{const id='g'+String(i).padStart(2,'0'),m=META[id],g={id,n,...CAT[c],...o};g.img=new Image();g.img.onload=minis;g.img.src=SPR[id];
g.w=Math.min(g.w,m.w*1.3);g.k=g.w/m.w;g.len=m.w;g.hh=m.h;g.cx=m.w/2;g.cy=m.h/2;g.ax=m.w*.4;g.ay=m.h*.55;g.mz=[m.w,m.h*m.my];g.ej=g.ej&&[g.ej[0]*m.w,g.ej[1]*m.h];return g});
function paint(c,g){c.drawImage(g.img,0,0)}
function mini(cn,g){const c=cn.getContext('2d'),k=Math.min((cn.width-24)/g.len,(cn.height-12)/g.hh);c.clearRect(0,0,cn.width,cn.height);c.save();c.translate(cn.width/2,cn.height/2);c.scale(k,k);c.translate(-g.cx,-g.cy);paint(c,g);c.restore()}
function minis(){document.querySelectorAll('#grid canvas').forEach((c,i)=>mini(c,G[i]));label()}

/* ---------- sound (all synthesised) ---------- */
let AC,MS;function ac(){if(!AC){AC=new(window.AudioContext||window.webkitAudioContext)();MS=AC.createGain();MS.gain.value=.8;MS.connect(AC.destination);
const d=AC.createDelay(),f=AC.createGain(),lp=AC.createBiquadFilter();d.delayTime.value=.13;f.gain.value=.3;lp.frequency.value=1800;MS.connect(d);d.connect(lp);lp.connect(f);f.connect(d);lp.connect(AC.destination)}if(AC.state=='suspended')AC.resume();return AC}
function nz(d){const c=ac(),b=c.createBuffer(1,c.sampleRate*d,c.sampleRate),a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*Math.pow(1-i/a.length,2);return b}
function shot(s){const c=ac(),t=c.currentTime,n=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();n.buffer=nz(s.d+.25);f.type='lowpass';f.frequency.setValueAtTime(s.f,t);f.frequency.exponentialRampToValueAtTime(300,t+s.d+.1);g.gain.setValueAtTime(s.v,t);g.gain.exponentialRampToValueAtTime(.001,t+s.d+.2);n.connect(f);f.connect(g);g.connect(MS);n.start(t);
const o=c.createOscillator(),og=c.createGain();o.frequency.setValueAtTime(s.t,t);o.frequency.exponentialRampToValueAtTime(35,t+.18);og.gain.setValueAtTime(s.v*.9,t);og.gain.exponentialRampToValueAtTime(.001,t+.22);o.connect(og);og.connect(MS);o.start(t);o.stop(t+.25)}
function tick(at,fr,v,d=.04){const c=ac(),t=c.currentTime+at,n=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();n.buffer=nz(d);f.type='bandpass';f.frequency.value=fr;g.gain.value=v;n.connect(f);f.connect(g);g.connect(MS);n.start(t)}
const sndReload=()=>{tick(0,1500,1.4);tick(.28,900,1.6,.07);tick(.7,2200,1.4)};
const sndSlide=()=>{const c=ac(),t=c.currentTime,n=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();n.buffer=nz(.4);f.type='bandpass';f.frequency.setValueAtTime(300,t);f.frequency.linearRampToValueAtTime(1000,t+.35);g.gain.value=.7;n.connect(f);f.connect(g);g.connect(MS);n.start(t);tick(.36,700,1.2)};

/* ---------- state ---------- */
const FX_SHEET_DATA = "data:image/png;base64,";
const fxImg = new Image();
fxImg.src = FX_SHEET_DATA;

const FX = {"flash_fireball": [[32, 17, 99, 79], [129, 15, 96, 75], [229, 19, 81, 77], [319, 28, 75, 49], [401, 36, 70, 37], [469, 33, 77, 38], [568, 36, 46, 33]], "flash_spiky": [[32, 94, 94, 75], [124, 94, 92, 68], [214, 94, 92, 70], [304, 101, 92, 56], [394, 105, 87, 46], [479, 103, 82, 46], [559, 114, 62, 36]], "flash_cone": [[33, 170, 91, 75], [134, 173, 82, 66], [214, 183, 92, 63], [304, 192, 94, 38], [418, 191, 63, 36], [479, 171, 82, 51], [559, 199, 15, 18]], "tracers": [[[652, 28, 144, 21], [794, 31, 102, 17], [894, 32, 99, 15]], [[657, 74, 139, 22], [794, 76, 96, 17], [915, 79, 71, 10]], [[652, 126, 144, 20], [794, 127, 102, 17], [894, 126, 102, 19]], [[649, 171, 147, 15], [794, 168, 102, 16], [894, 164, 101, 21]], [[637, 202, 159, 24], [794, 202, 99, 24], [913, 208, 83, 13]]], "casings": [[668, 261, 33, 31], [721, 273, 30, 27], [778, 267, 26, 34], [845, 269, 34, 26], [908, 266, 33, 33], [939, 257, 45, 42]], "sparks": [[669, 337, 32, 36], [699, 332, 62, 43], [759, 326, 72, 61], [829, 324, 82, 68], [909, 320, 82, 78]], "smoke_soft": [[32, 239, 76, 72], [118, 251, 71, 59], [201, 243, 80, 77], [279, 245, 102, 74], [379, 245, 107, 76], [484, 253, 72, 64], [554, 260, 67, 51]], "smoke_billow": [[31, 333, 78, 73], [116, 330, 83, 68], [209, 335, 93, 71], [314, 330, 89, 72], [417, 339, 94, 60], [528, 324, 89, 82]], "smoke_heavy": [[30, 404, 97, 96], [131, 407, 91, 98], [233, 404, 96, 104], [333, 413, 94, 98], [433, 405, 98, 103], [536, 404, 90, 105]], "smoke_rings": [[29, 511, 86, 94], [127, 520, 83, 86], [223, 504, 87, 100], [319, 508, 110, 94], [446, 504, 98, 102], [559, 504, 157, 102], [714, 504, 157, 86], [869, 504, 112, 102]], "smoke_wisps": [[115, 599, 161, 72], [274, 599, 105, 72], [392, 599, 189, 72], [579, 599, 102, 64], [679, 614, 152, 56], [829, 599, 152, 72]]};

let sel=0,held=false,hp={x:0,y:0},ang=0,flip=false,reloading=false,last=0,kick=0,shake=0,flashT=0,wisp=0,wispT=0,shots=0,firedOnce=false,hover=false;
let barrelHeat=0, fxFlashStyle='auto', fxSmokeStyle='full';
let mode='',hl=null,hand=null,td=false,prevTD=true,fistF=0,openF=0,lt=-1,T={};
const ammo=G.map(g=>g.mag),mouse={x:0,y:0,down:false,click:false};
const sm=[],rings=[],cas=[],bullets=[],flashes=[],wisps=[],sparks=[];
const R_=()=>({x:Math.max(200,Math.min(W*.2,300)),y:Math.max(H*.5,H-300)});
const rad=()=>{const g=G[sel];return g.len*g.k/2+50};

/* ---------- hand reading ---------- */
function mp(l){const vw=vid.videoWidth,vh=vid.videoHeight,s=Math.max(W/vw,H/vh);return[W-(l.x*vw*s-(vw*s-W)/2),l.y*vh*s-(vh*s-H)/2]}
function readHand(lm){const d=(i,j)=>Math.hypot(lm[i].x-lm[j].x,lm[i].y-lm[j].y),sz=d(0,9);
const e=[[8,6],[12,10],[16,14],[20,18]].map(([t,p])=>d(t,0)>d(p,0)*1.08),n=e.filter(Boolean).length;
const pose=n==4?'open':(e[0]&&!e[1]&&!e[2]&&!e[3])?'point':n==0?'fist':'other';
const ps=[0,5,9,13,17].map(i=>mp(lm[i])),w=mp(lm[0]),t=mp(lm[8]),th=d(4,10)/sz;
if(th<.6)td=true;else if(th>.85)td=false;
return{x:ps.reduce((s,q)=>s+q[0],0)/5,y:ps.reduce((s,q)=>s+q[1],0)/5,pose,a:Math.atan2(t[1]-w[1],t[0]-w[0]),td}}

/* ---------- smoke / fx helpers ---------- */
const rnd=(a,b)=>a+Math.random()*(b-a);
function world(px,py){const g=G[sel],lx=(px-T.ax)*g.k,ly=(py-T.ay)*g.k*(T.fl?-1:1),c=Math.cos(T.a),s=Math.sin(T.a);return[T.x+lx*c-ly*s,T.y+lx*s+ly*c]}

function fire(now){
  const g=G[sel];
  if(reloading||ammo[sel]<=0||now-last<g.rate)return;
  last=now;ammo[sel]--;kick=1;shake=Math.max(shake,g.sk);flashT=.08;shots++;firedOnce=true;shot(g.s);
  
  if(!held){hp={x:R_().x+(g.ax-g.cx)*g.k,y:R_().y+(g.ay-g.cy)*g.k};ang=0;flip=false;}
  T=tf();
  const m=world(...g.mz),dx=Math.cos(T.a),dy=Math.sin(T.a);

  // 1. Muzzle Flash Animation
  let ftype = fxFlashStyle;
  if(ftype === 'auto'){
    if(g.big || g.t==='Launcher' || g.t==='Shotgun' || g.t==='Sniper' || g.t==='LMG') ftype = 'fireball';
    else if(g.t==='SMG' || g.t==='Rifle') ftype = 'spiky';
    else ftype = 'cone';
  }
  const fFrames = FX['flash_' + ftype] || FX.flash_spiky;
  flashes.push({
    x: m[0], y: m[1],
    a: T.a,
    frames: fFrames,
    age: 0,
    life: g.big ? 0.13 : 0.09,
    scale: (g.big ? 1.5 : 1.1) * (g.k || 1),
    flip: T.fl
  });

  // 2. High-speed Bullet Tracer
  const trIdx = (shots % FX.tracers.length);
  bullets.push({
    x: m[0] + dx * 20, y: m[1] + dy * 20,
    vx: dx * 3400, vy: dy * 3400,
    a: T.a,
    frame: FX.tracers[trIdx][0],
    age: 0,
    life: 0.35,
    scale: (g.big ? 1.3 : 0.95) * (g.k || 1)
  });

  // 3. Tumbling 3D Brass Shell Casings
  if(g.cs){
    const e = world(...g.ej), nx = -dy, ny = dx, sg = (ny < 0 || T.fl) ? 1 : -1;
    cas.push({
      x: e[0], y: e[1],
      vx: nx * sg * rnd(140, 260) - dx * rnd(0, 60),
      vy: ny * sg * rnd(140, 260) - dy * rnd(0, 60) - 130,
      rot: rnd(0, 6.28),
      sp: rnd(-18, 18),
      frameIdx: Math.floor(rnd(0, FX.casings.length)),
      age: 0,
      life: 2.2,
      scale: (g.big ? 1.15 : 0.85) * (g.k || 1),
      isShotgun: g.t === 'Shotgun'
    });
  }

  // 4. Animated Shockwave Smoke Rings
  if(fxSmokeStyle !== 'wisps'){
    rings.push({
      x: m[0] + dx * 16, y: m[1] + dy * 16,
      dx, dy, a: T.a,
      v: rnd(170, 270),
      age: 0,
      life: g.big ? 0.85 : 0.65,
      scale: (g.big ? 1.5 : 1.0) * (g.k || 1)
    });
  }

  // 5. Animated Smoke Clouds
  if(fxSmokeStyle !== 'wisps'){
    const n = g.big ? 9 : (g.auto ? 4 : 6);
    for(let i = 0; i < n; i++){
      const pType = (g.big || fxSmokeStyle === 'heavy') ? 'heavy' : (i % 2 === 0 ? 'billow' : 'soft');
      const pFrames = FX['smoke_' + pType];
      sm.push({
        x: m[0] + dx * rnd(0, 25),
        y: m[1] + dy * rnd(0, 25),
        vx: dx * rnd(60, g.big ? 320 : 210) + rnd(-35, 35),
        vy: dy * rnd(60, g.big ? 320 : 210) + rnd(-35, 35) - 25,
        rot: rnd(0, 6.28),
        rotSp: rnd(-1.4, 1.4),
        frames: pFrames,
        frameOffset: Math.floor(rnd(0, 2)),
        age: 0,
        life: rnd(1.3, g.big ? 3.0 : 2.2),
        al: rnd(0.5, 0.8),
        scale: rnd(0.75, 1.2) * (g.big ? 1.4 : 1.0) * (g.k || 1),
        dr: rnd(1.2, 1.9)
      });
    }
    if(g.back){
      const q = world(0, g.mz[1]);
      for(let i = 0; i < 8; i++){
        sm.push({
          x: q[0], y: q[1],
          vx: -dx * rnd(90, 300) + rnd(-35, 35),
          vy: -dy * rnd(90, 300) + rnd(-35, 35) - 20,
          rot: rnd(0, 6.28), rotSp: rnd(-1.5, 1.5),
          frames: FX.smoke_heavy, frameOffset: 0,
          age: 0, life: rnd(1.8, 3.2), al: rnd(0.5, 0.8),
          scale: rnd(1.0, 1.5) * (g.k || 1), dr: 1.5
        });
      }
    }
  }

  // 6. Barrel Heat for Post-Shot Smoke Wisps
  barrelHeat = Math.min(barrelHeat + 0.35, 2.0);
  wisp = Math.max(wisp, 3.6 + barrelHeat * 1.5);

  if(ammo[sel]==0)setTimeout(reload,450);
}

function reload(){if(reloading||ammo[sel]==G[sel].mag)return;reloading=true;sndReload();const i=sel;setTimeout(()=>{ammo[i]=G[i].mag;reloading=false},G[sel].rl)}

/* ---------- grab / release / select ---------- */
function grab(){const g=G[sel],r=R_();held=true;hp={x:r.x+(g.ax-g.cx)*g.k,y:r.y+(g.ay-g.cy)*g.k};ang=0;flip=false;fistF=0;openF=0;prevTD=true;tick(0,1200,1.2)}
function drop(){if(!held)return;held=false;firedOnce=false;sndSlide()}
function choose(i){drop();sel=i;sndSlide();label()}
function label(){const g=G[sel];$('#pick b').innerHTML=g.n+' <i>'+g.t+'</i>';$('#pick2 small').textContent=g.n+' '+g.t+' selected';mini($('#pick canvas'),g)}
function openDrawers(){$('#drawers').hidden=false;$('#intro').style.visibility='hidden';sndSlide();$('#grid').querySelectorAll('button').forEach((b,i)=>b.classList.toggle('on',i==sel))}
function closeDrawers(){$('#drawers').hidden=true;$('#intro').style.visibility=''}
$('#grid').innerHTML=G.map((g,i)=>`<button data-i="${i}"><canvas width="340" height="130"></canvas><b>${g.n}</b><i>${g.t} · ${g.mag} rounds</i></button>`).join('');
$('#grid').onclick=e=>{const b=e.target.closest('button');if(b){choose(+b.dataset.i);closeDrawers()}};
$('#x').onclick=closeDrawers;$('#pick').onclick=$('#pick2').onclick=openDrawers;$('#sw').onclick=()=>sel==null||openDrawers();
$('#rs').onclick=()=>{drop();ammo.forEach((_,i)=>ammo[i]=G[i].mag);reloading=false;sm.length=rings.length=cas.length=bullets.length=flashes.length=wisps.length=sparks.length=0;wisp=barrelHeat=0};
$('#fire-btn').onclick=()=>fire(performance.now());

const fxFlashEl=$('#fx-flash'), fxSmokeEl=$('#fx-smoke');
if(fxFlashEl) fxFlashEl.onchange=e=>{fxFlashStyle=e.target.value};
if(fxSmokeEl) fxSmokeEl.onchange=e=>{fxSmokeStyle=e.target.value};

/* ---------- start ---------- */
function begin(m){mode=m;$('#intro').hidden=true;$('#hud').hidden=false;$('#fxbar').hidden=false;ac()}
$('#mouse').onclick=()=>begin('mouse');
$('#go').onclick=async()=>{const b=$('#go');ac();b.textContent='Starting camera…';
try{vid.srcObject=await navigator.mediaDevices.getUserMedia({video:{width:1280,height:720,facingMode:'user'}});await vid.play();vid.classList.add('on');b.textContent='Loading hand tracking…';
const v='0.10.14',{HandLandmarker:HL,FilesetResolver:FR}=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@'+v+'/+esm'),fs=await FR.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@'+v+'/wasm'),
o={baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task',delegate:'GPU'},runningMode:'VIDEO',numHands:1};
try{hl=await HL.createFromOptions(fs,o)}catch(e){o.baseOptions.delegate='CPU';hl=await HL.createFromOptions(fs,o)}
begin('cam')}catch(e){console.error(e);b.textContent='Camera or tracking failed — use mouse mode'}};
addEventListener('pointermove',e=>{mouse.x=e.clientX;mouse.y=e.clientY});
cv.addEventListener('pointerdown',e=>{if(e.button==0){mouse.down=true;mouse.click=true}});
addEventListener('pointerup',()=>mouse.down=false);
addEventListener('contextmenu',e=>{if(mode=='mouse'){e.preventDefault();drop()}});
addEventListener('keydown',e=>{
  if(e.key==='Escape')drop();
  if(e.key==='r'||e.key==='R')reload();
  if(e.key==='ArrowRight')choose((sel+1)%G.length);
  if(e.key==='ArrowLeft')choose((sel+G.length-1)%G.length);
  if(e.code==='Space'){e.preventDefault();fire(performance.now())}
  if(e.key==='f'||e.key==='F'){
    const styles=['auto','fireball','spiky','cone'];
    fxFlashStyle=styles[(styles.indexOf(fxFlashStyle)+1)%styles.length];
    if(fxFlashEl) fxFlashEl.value=fxFlashStyle;
  }
  if(e.key==='s'||e.key==='S'){
    const styles=['full','heavy','wisps'];
    fxSmokeStyle=styles[(styles.indexOf(fxSmokeStyle)+1)%styles.length];
    if(fxSmokeEl) fxSmokeEl.value=fxSmokeStyle;
  }
});

/* ---------- frame ---------- */
function ell(x,y,rx,ry){X.beginPath();X.ellipse(x,y,rx,ry,0,0,7);X.fill();X.stroke()}
function stand(r,g){const rx=g.len*g.k/2+26,ty=r.y+26,gr=X.createLinearGradient(r.x-5,0,r.x+5,0);gr.addColorStop(0,'#a8863d');gr.addColorStop(.5,'#f0d98c');gr.addColorStop(1,'#a8863d');
X.fillStyle=gr;X.fillRect(r.x-5,ty+20,10,H-ty-48);X.lineWidth=2;X.strokeStyle='#d9b862';X.fillStyle='#15161c';ell(r.x,H-32,70,13);X.lineWidth=3;ell(r.x,ty,rx,34);X.lineWidth=1;X.strokeStyle='rgba(217,184,98,.6)';X.beginPath();X.ellipse(r.x,ty,rx-14,24,0,0,7);X.stroke()}
let prev=performance.now();

function frame(now){
  requestAnimationFrame(frame);
  const dt=Math.min((now-prev)/1000,.05);prev=now;
  const g=G[sel],r=R_(),R=rad();

  if(mode=='cam'&&hl&&vid.readyState>=2&&vid.currentTime!=lt){
    lt=vid.currentTime;
    const o=hl.detectForVideo(vid,now);
    if(o.landmarks&&o.landmarks[0]){hand=readHand(o.landmarks[0]);hand.t=now}
    else if(hand&&now-hand.t>500)hand=null;
  }

  const inp=mode=='cam'?hand:mode=='mouse'?{x:mouse.x,y:mouse.y}:null;
  if(!held){
    hover=!!inp&&Math.hypot(inp.x-r.x,inp.y-r.y)<R;
    if(mode=='cam'){fistF=hover&&hand.pose=='fist'?fistF+1:0;if(fistF>6)grab()}
    else if(mode=='mouse'&&mouse.click&&hover)grab();
  } else {
    let tx=hp.x,ty=hp.y,ta=flip?Math.PI:0,trig=false;
    if(mode=='cam'&&hand){
      tx=hand.x;ty=hand.y;ta=hand.pose=='point'?hand.a:(hand.x<W/2?0:Math.PI);
      if(hand.pose=='point'){trig=g.auto?hand.td:(hand.td&&!prevTD);prevTD=hand.td}else prevTD=true;
      openF=hand.pose=='open'?openF+1:0;if(openF>14)drop();
    } else if(mode=='mouse'){
      tx=mouse.x;ty=mouse.y;ta=mouse.x<W/2?0:Math.PI;trig=g.auto?mouse.down:mouse.click;
    }
    const a=1-Math.exp(-dt*18);hp.x+=(tx-hp.x)*a;hp.y+=(ty-hp.y)*a;
    let df=ta-ang;df=Math.atan2(Math.sin(df),Math.cos(df));ang+=df*(1-Math.exp(-dt*14));
    flip=Math.cos(ang)<0;
    if(held&&trig){T=tf();fire(now)}
  }
  mouse.click=false;

  kick*=Math.exp(-dt*9);shake*=Math.exp(-dt*11);flashT=Math.max(0,flashT-dt);T=tf();

  // Post-shot Barrel Smoke Wisps (curling smoke trails rising from hot barrel)
  if(wisp > 0){
    wisp -= dt;
    wispT -= dt;
    barrelHeat = Math.max(0, barrelHeat - dt * 0.22);
    if(wispT <= 0){
      wispT = rnd(0.06, 0.12);
      const m = world(...g.mz);
      const wi = Math.floor(rnd(0, FX.smoke_wisps.length));
      wisps.push({
        x: m[0], y: m[1],
        vx: (Math.cos(T.a) * 12 || 0) + rnd(-10, 10),
        vy: rnd(-36, -80),
        rot: rnd(-0.6, 0.6),
        rotSp: rnd(-0.5, 0.5),
        swaySpeed: rnd(2.2, 4.2),
        swayAmp: rnd(14, 28),
        frame: FX.smoke_wisps[wi],
        scale: rnd(0.45, 0.75) * (barrelHeat > 0.8 ? 1.3 : 1.0) * (g.k || 1),
        growth: rnd(18, 38),
        age: 0,
        life: rnd(2.2, 3.8),
        al: rnd(0.4, 0.7) * Math.min(1, barrelHeat * 0.7 + 0.4)
      });
    }
  }

  // Update particles
  for(const p of sm){
    p.age+=dt;const k=Math.exp(-p.dr*dt);p.vx*=k;p.vy=p.vy*k-28*dt;
    p.x+=(p.vx+Math.sin(p.age*2.4+p.rot)*12)*dt;p.y+=p.vy*dt;
    p.rot+=p.rotSp*dt;p.scale+=(dt*0.28);
  }
  for(const q of rings){
    q.age+=dt;q.x+=q.dx*q.v*dt;q.y+=q.dy*q.v*dt-12*dt;
    q.v*=Math.exp(-1.4*dt);q.scale+=(dt*0.65);
  }
  for(const c of cas){
    c.age+=dt;c.vy+=850*dt;c.x+=c.vx*dt;c.y+=c.vy*dt;c.rot+=c.sp*dt;
  }
  for(const b of bullets){
    b.age+=dt;b.x+=b.vx*dt;b.y+=b.vy*dt;
    if(b.age>=b.life && Math.random()<0.6){
      sparks.push({x:b.x,y:b.y,age:0,life:0.18,scale:rnd(0.5,0.85)});
    }
  }
  for(const f of flashes) f.age+=dt;
  for(const w of wisps){
    w.age+=dt;w.x+=(w.vx+Math.sin(w.age*w.swaySpeed)*w.swayAmp)*dt;
    w.y+=w.vy*dt;w.rot+=w.rotSp*dt;w.scale+=(w.growth/100)*dt;
  }
  for(const s of sparks) s.age+=dt;

  // Cleanup expired
  for(const a of[sm,rings,cas,bullets,flashes,wisps,sparks]){
    for(let i=a.length-1;i>=0;i--)if(a[i].age>(a[i].life||1.5))a.splice(i,1);
  }

  // Draw scene
  X.clearRect(0,0,W,H);
  X.save();
  if(shake>.05)X.translate(rnd(-1,1)*shake*6,rnd(-1,1)*shake*6);
  stand(r,g);

  if(!held){
    X.beginPath();X.arc(r.x,r.y,R,0,7);
    X.strokeStyle=hover?'rgba(255,255,255,.95)':'rgba(255,255,255,.55)';
    X.lineWidth=1.5;X.stroke();
    if(fistF){
      X.beginPath();X.arc(r.x,r.y,R,-Math.PI/2,-Math.PI/2+Math.min(fistF/7,1)*6.283);
      X.strokeStyle='#fffee8';X.lineWidth=4;X.stroke();
    }
    if(mode=='cam'&&hand){X.beginPath();X.arc(hand.x,hand.y,9,0,7);X.strokeStyle='#fff';X.lineWidth=2;X.stroke()}
  }

  // Draw Gun
  X.save();
  X.translate(T.x,T.y);
  X.rotate(T.a);
  X.scale(g.k,T.fl?-g.k:g.k);
  X.translate(-T.ax,-T.ay);
  paint(X,g);
  X.restore();

  // Draw Bullets / Tracers
  for(const b of bullets){
    const [sx,sy,sw,sh]=b.frame;
    const al=Math.max(0,1-(b.age/b.life)*0.8);
    X.save();X.globalAlpha=al;X.translate(b.x,b.y);X.rotate(b.a);X.scale(b.scale,b.scale);
    X.drawImage(fxImg,sx,sy,sw,sh,-sw*0.8,-sh/2,sw,sh);
    X.globalCompositeOperation='lighter';X.globalAlpha=al*0.65;
    X.drawImage(fxImg,sx,sy,sw,sh,-sw*0.8,-sh/2,sw,sh);
    X.restore();
  }

  // Draw Tumbling Brass Shell Casings
  for(const c of cas){
    const fIdx=(c.frameIdx+Math.floor(c.age*18))%FX.casings.length;
    const [sx,sy,sw,sh]=FX.casings[fIdx];
    const al=Math.min(1,(c.life-c.age)*2.5);
    X.save();X.globalAlpha=al;X.translate(c.x,c.y);X.rotate(c.rot);X.scale(c.scale,c.scale);
    if(c.isShotgun){X.fillStyle='#c0392b';X.fillRect(-sw*.35,-sh*.35,sw*.7,sh*.7)}
    X.drawImage(fxImg,sx,sy,sw,sh,-sw/2,-sh/2,sw,sh);
    X.restore();
  }

  // Draw Animated Smoke Clouds
  for(const p of sm){
    const prog=p.age/p.life;
    const fi=Math.min(Math.floor((prog*(p.frames.length-p.frameOffset))+p.frameOffset),p.frames.length-1);
    const [sx,sy,sw,sh]=p.frames[fi];
    const al=p.al*Math.min(1,p.age*7)*Math.pow(1-prog,1.4);
    X.save();X.globalAlpha=Math.max(0,Math.min(1,al));
    X.translate(p.x,p.y);X.rotate(p.rot);X.scale(p.scale,p.scale);
    X.drawImage(fxImg,sx,sy,sw,sh,-sw/2,-sh/2,sw,sh);
    X.restore();
  }

  // Draw Animated Shockwave Smoke Rings
  for(const q of rings){
    const prog=q.age/q.life;
    const ri=Math.min(Math.floor(prog*FX.smoke_rings.length),FX.smoke_rings.length-1);
    const [sx,sy,sw,sh]=FX.smoke_rings[ri];
    const al=0.85*Math.min(1,q.age*6)*Math.pow(1-prog,1.3);
    X.save();X.globalAlpha=Math.max(0,Math.min(1,al));
    X.translate(q.x,q.y);X.rotate(q.a);X.scale(q.scale,q.scale);
    X.drawImage(fxImg,sx,sy,sw,sh,-sw*0.3,-sh/2,sw,sh);
    X.restore();
  }

  // Draw Animated Post-shot Curling Smoke Wisps (rising after shooting)
  for(const w of wisps){
    const prog=w.age/w.life;
    const [sx,sy,sw,sh]=w.frame;
    const al=w.al*Math.min(1,w.age*4.5)*Math.pow(1-prog,1.25);
    X.save();X.globalAlpha=Math.max(0,Math.min(1,al));
    X.translate(w.x,w.y);X.rotate(w.rot);X.scale(w.scale,w.scale);
    X.drawImage(fxImg,sx,sy,sw,sh,-sw/2,-sh/2,sw,sh);
    X.restore();
  }

  // Draw Animated Muzzle Flashes
  for(const f of flashes){
    const prog=f.age/f.life;
    const fi=Math.min(Math.floor(prog*f.frames.length),f.frames.length-1);
    const [sx,sy,sw,sh]=f.frames[fi];
    X.save();X.translate(f.x,f.y);X.rotate(f.a);X.scale(f.scale,f.flip?-f.scale:f.scale);
    X.drawImage(fxImg,sx,sy,sw,sh,0,-sh/2,sw,sh);
    X.globalCompositeOperation='lighter';X.globalAlpha=Math.max(0,1-prog)*0.85;
    X.drawImage(fxImg,sx,sy,sw,sh,-sw*0.05,-sh*0.55,sw*1.1,sh*1.1);
    X.restore();
  }

  // Draw Impact Sparks
  for(const s of sparks){
    const prog=s.age/s.life;
    const si=Math.min(Math.floor(prog*FX.sparks.length),FX.sparks.length-1);
    const [sx,sy,sw,sh]=FX.sparks[si];
    X.save();X.globalCompositeOperation='lighter';X.globalAlpha=Math.max(0,1-prog);
    X.translate(s.x,s.y);X.scale(s.scale,s.scale);
    X.drawImage(fxImg,sx,sy,sw,sh,-sw/2,-sh/2,sw,sh);
    X.restore();
  }

  // Screen Ambient Flash
  if(flashT>0){
    const m=world(...g.mz),f=flashT/.08;
    X.fillStyle=`rgba(255,200,120,${f*.09})`;
    X.fillRect(-20,-20,W+40,H+40);
  }

  X.restore();
  hud();
}

function tf(){
  const g=G[sel];
  if(!held){const r=R_();return{x:r.x,y:r.y,a:-.04,fl:0,ax:g.cx,ay:g.cy}}
  const d=kick*16*g.rc*g.k;
  return{x:hp.x-Math.cos(ang)*d,y:hp.y-Math.sin(ang)*d,a:ang+(flip?1:-1)*kick*.14*g.rc,fl:flip,ax:g.ax,ay:g.ay}
}

function hud(){
  if(!mode)return;
  const g=G[sel],cam=mode=='cam',n=ammo[sel],st=!held?1:firedOnce?3:2;
  $('#lab').textContent='Step '+st+' of 3 · '+(reloading?'reloading':held?(performance.now()-last<250?'firing':'armed'):'resting');
  $('#ins').textContent=[cam?'Close your fist inside the circle to pick the gun up':'Click inside the circle to pick the gun up',cam?'Point like a finger gun, raise your thumb, then drop it to fire':'Click to fire · hold for full auto',cam?'Open your palm to put it back':'Right-click or Esc to put it back'][st-1];
  $('#am').textContent=(reloading?'reloading…':n+' / '+g.mag+' rounds')+' · '+g.n+(g.auto?' · full auto':' · semi auto');
  $('#bar i').style.width=(reloading?0:n/g.mag*100)+'%';
  const stEl=$('#fx-stats');
  if(stEl){
    const totalFx = sm.length + rings.length + cas.length + bullets.length + flashes.length + wisps.length;
    stEl.textContent = totalFx ? (totalFx + ' fx active') : (barrelHeat > 0.05 ? 'barrel hot' : 'ready');
  }
}

label();
requestAnimationFrame(frame);
